module sub_64bit
(
    input [63:0] A,
    input [63:0] B,
    output [63:0] result,
    output overflow
);
    wire [63:0] temp_result;
    wire [63:0] borrow;

    assign {borrow, temp_result} = A - B;

    assign overflow = ((A[63] && !B[63] && !temp_result[63]) || (!A[63] && B[63] && temp_result[63])) ? 1'b1 : 1'b0;

    assign result = temp_result;
endmodule

module comparator_3bit
(
    input [2:0] A,
    input [2:0] B,
    output A_greater,
    output A_equal,
    output A_less
);

assign A_greater = (A > B);
assign A_equal = (A == B);
assign A_less = (A < B);
