module div_16bit
(
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

reg [15:0] a_reg;
reg [7:0] b_reg;

always @(*) begin

    a_reg = A;
    b_reg = B;

    result = 0;
    odd = 0;

    if (b_reg == 0) begin
        result = 0;
        odd = A;
    end else begin
        result = a_reg / b_reg;
        odd = a_reg % b_reg;
    end
end
endmodule

module parallel2serial
(
    input clk,
    input rst_n,
    input [3:0] d,
    output valid_out,
    output dout
);
    reg [1:0] cnt;
    reg [3:0] data;
    reg valid;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 2'b00;
            data <= 4'b0000;
            valid <= 1'b0;
        end else begin
            if (cnt == 2'b11) begin
                data <= d;
                cnt <= 2'b00;
                valid <= 1'b1;
            end else begin
                cnt <= cnt + 1;
                valid <= 1'b0;

                data <= {data[2:0], data[3]};
            end
        end
    end

    assign dout = data[3];
    assign valid_out = valid;
endmodule

module multi_8bit
(
    input [7:0] A,
    input [7:0] B,
    output reg [15:0] product
);
    integer i;

    always @(*) begin
        product = 16'b0; 

        for (i = 0; i < 8; i = i + 1) begin
            if (B[i]) begin
                product = product + (A << i); 
            end
        end
    end

endmodule

module fixed_point_adder
(
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

parameter Q = 8;
parameter N = 16;

wire [Q-1:0] a_frac, b_frac;
wire [N-Q-1:0] a_int, b_int;

assign {a_int, a_frac} = a;
assign {b_int, b_frac} = b;

wire [Q:0] sum_frac = a_frac + b_frac;
wire [N-Q-1:0] sum_int = a_int + b_int;

assign c = {sum_int, sum_frac[Q-1:0]};

endmodule

module multi_booth_8bit
(
    input clk,
    input reset,
    input [7:0] a,
    input [7:0] b,
    output reg [15:0] p,
    output reg rdy
);
    reg [15:0] multiplier, multiplicand;
    reg [4:0] ctr;

    always @(posedge clk or posedge (reset)) begin
        if(reset) begin
            multiplier <= {{8{a[7]}}, a};
            multiplicand <= {{8{b[7]}}, b};
            ctr <= 5'b0;
            p <= 16'b0;
            rdy <= 1'b0;
        end else begin
            if(ctr < 5'd16) begin
                if(multiplier[ctr])
                    p <= p + multiplicand;

                multiplicand <= multiplicand << 1;
                ctr <= ctr + 1;
            end else begin
                rdy <= 1'b1;
            end
        end
    end

endmodule

module fixed_point_subtractor
(
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

parameter Q = 8;
parameter N = Q + 8;

reg [N-1:0] res;

always @(*) begin
    if (a[N-1] == b[N-1]) begin
        res = a - b;
        if (res[N-1] == 1'b1) begin
            res[N-1] = 1'b0;
        end
    end else begin
        if (a[N-1] == 1'b0 && b[N-1] == 1'b1) begin
            res = a + (~b + 1);
            if (res[N-1] == 1'b1) begin
                res[N-1] = 1'b0;
            end
        end else begin
            res = ~a + 1 + b;
            if (res[N-1] == 1'b1) begin
                res[N-1] = 1'b0;
            end
        end
    end

    c = res;
end

endmodule

module freq_divbyfrac
(
    input clk,
    input rst_n,
    output clk_div
);
    parameter MUL2_DIV_CLK = 7;
    reg [3:0] cnt;
    reg clk_ave_r, clk_adjust_r;
    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) cnt <= 4'd0;
        else if(cnt == MUL2_DIV_CLK - 1) cnt <= 4'd0;
        else cnt <= cnt + 1;
    end

    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) clk_ave_r <= 1'b0;
        else if((cnt == 4'd0)||(cnt == 4'd4)) clk_ave_r <= 1'b1;
        else clk_ave_r <= 1'b0;
    end

    always @(negedge clk or negedge rst_n) begin
        if(!rst_n) clk_adjust_r <= 1'b0;
        else if((cnt == 4'd1)||(cnt == 4'd4)) clk_adjust_r <= 1'b1;
        else clk_adjust_r <= 1'b0;
    end

    assign clk_div = clk_adjust_r | clk_ave_r;
endmodule

module freq_div
(
    input CLK_in,
    input RST,
    output reg CLK_50,
    output reg CLK_10,
    output reg CLK_1
);
    reg [3:0] cnt_10;
    reg [6:0] cnt_100;

    always @(posedge CLK_in or posedge RST) begin
        if (RST) begin
            CLK_50 <= 1'b0;
        end else begin
            CLK_50 <= ~CLK_50;
        end
    end

    always @(posedge CLK_in or posedge RST) begin
        if (RST) begin
            CLK_10 <= 1'b0;
            cnt_10 <= 4'b0000;
        end else begin
            if (cnt_10 == 4'b0100) begin
                CLK_10 <= ~CLK_10;
                cnt_10 <= 4'b0000;
            end else begin
                cnt_10 <= cnt_10 + 1;
            end
        end
    end

    always @(posedge CLK_in or posedge RST) begin
        if (RST) begin
            CLK_1 <= 1'b0;
            cnt_100 <= 7'b0000000;
        end else begin
            if (cnt_100 == 7'b0110011) begin
                CLK_1 <= ~CLK_1;
                cnt_100 <= 7'b0000000;
            end else begin
                cnt_100 <= cnt_100 + 1;
            end
        end
    end
endmodule

module fsm
(
    input IN,
    input CLK,
    input RST,
    output MATCH
);

localparam s0 = 3'b000;
localparam s1 = 3'b001;
localparam s2 = 3'b010;
localparam s3 = 3'b011;
localparam s4 = 3'b100;
localparam s5 = 3'b101;

reg [2:0] ST_cr, ST_nr;

always @(*) begin
    case(ST_cr)
        s0: begin
            if(IN) ST_nr = s1;
            else   ST_nr = s0;
        end

        s1: begin
            if(IN) ST_nr = s1;
            else   ST_nr = s2;
        end

        s2: begin
            if(IN) ST_nr = s1;
            else   ST_nr = s3;
        end

        s3: begin
            if(IN) ST_nr = s4;
            else   ST_nr = s0;
        end

        s4: begin
            if(IN) ST_nr = s5;
            else   ST_nr = s2;
        end

        s5: begin
            if(IN) ST_nr = s1;
            else   ST_nr = s2;
        end

        default: ST_nr = s0;
    endcase
end

always @(posedge CLK or posedge RST) begin
    if(RST) ST_cr <= s0; else ST_cr <= ST_nr;
end

assign MATCH = (RST) ? 1'b0 :
               ((ST_cr == s4) && (IN == 1)) ? 1'b1 : 1'b0;
endmodule

module edge_detect
(
    input clk,
    input rst_n,
    input a,
    output rise,
    output down
);
    reg a_prev;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            a_prev <= 1'b0;
        end else begin
            a_prev <= a;
        end
    end

    assign rise = (a && ~a_prev);
    assign down = (~a && a_prev);
endmodule

module instr_reg
(
    input clk,
    input rst,
    input [1:0] fetch,
    input [7:0] data,
    output [2:0] ins,
    output [4:0] ad1,
    output [7:0] ad2
);
    reg [7:0] ins_p1, ins_p2;

    always @(posedge clk or negedge rst) begin
        if(!rst) begin
            ins_p1 <= 8'b0;
            ins_p2 <= 8'b0;
        end
        else begin
            case(fetch)
                2'b01: ins_p1 <= data;
                2'b10: ins_p2 <= data;
                default: begin
                    ins_p1 <= ins_p1;
                    ins_p2 <= ins_p2;
                end
            endcase
        end
    end

    assign ins = ins_p1[7:5];
    assign ad1 = ins_p1[4:0];
    assign ad2 = ins_p2;
endmodule

module width_8to16
(
    input clk,
    input rst_n,
    input valid_in,
    input [7:0] data_in,
    output reg valid_out,
    output reg [15:0] data_out
);
    reg [7:0] data_lock;
    reg flag;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            data_out <= 16'b0;
            data_lock <= 8'b0;
            flag <= 1'b0;
            valid_out <= 1'b0;
        end else begin
            if (valid_in && !flag) begin
                data_lock <= data_in;
                flag <= 1'b1;
            end else if (valid_in && flag) begin
                data_out <= {data_lock, data_in};
                valid_out <= 1'b1;
                flag <= 1'b0;
            end else begin
                valid_out <= 1'b0;
            end
        end
    end
endmodule

