module pulse_detect
(
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

localparam s0 = 2'b00;
localparam s1 = 2'b01;
localparam s2 = 2'b10;
localparam s3 = 2'b11;

reg [1:0] state, next_state;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) state <= s0; else state <= next_state;
end

always @(*) begin

    next_state = state;
    data_out = 1'b0;

    case(state)
        s0: begin
            if(data_in == 1'b0) next_state = s1; else next_state = s0;
        end

        s1: begin
            if(data_in == 1'b1) next_state = s2; else next_state = s1;
        end

        s2: begin
            if(data_in == 1'b0) next_state = s3; else next_state = s0;
        end

        s3: begin
            if(data_in == 1'b1) next_state = s2; else next_state = s1;
        end
    endcase

    if((state == s2) && (data_in == 1'b0))
        data_out = 1'b1;
end
endmodule

