module multi_pipe_4bit
#(
    parameter size = 4
)
(
    input clk,
    input rst_n,
    input mul_a,
    input mul_b,
    output reg mul_out
);

reg [size-1:0] stage1_mul;
reg [size*2-1:0] stage2_mul;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        stage1_mul <= 0;
        stage2_mul <= 0;
        mul_out <= 0;
    end else begin
        stage1_mul <= mul_a * mul_b;
        stage2_mul <= {stage1_mul[0], stage1_mul[size-1:1]};
        mul_out <= stage2_mul;
    end
end

endmodule

module traffic_light
(
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output reg red
);

reg [7:0] counter;
reg [7:0] green_time;
reg [7:0] yellow_time;
reg [7:0] red_time;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        counter <= 8'b0;
        green_time <= 8'd60;
        yellow_time <= 8'd5;
        red_time <= 8'd10;
        red <= 1'b1;
    end else begin
        if (counter == green_time - 1) begin
            counter <= 8'b0;
            red <= 1'b1;
        end else if (counter == green_time + yellow_time - 1) begin
            counter <= 8'b0;
            red <= 1'b1;
        end else if (counter == green_time + yellow_time + red_time - 1) begin
            counter <= 8'b0;
            red <= 1'b0;
        end else begin
            counter <= counter + 1;
        end
    end
end

assign clock = {red, red, red, red, red, red, red, red};

endmodule

