module adder_pipe_64bit
(
    input clk,
    input rst_n,
    input i_en,
    input [63:0] adda,
    input [63:0] addb,
    output [64:0] result,
    output o_en
);

reg [63:0] reg_a, reg_b;
reg [64:0] sum;
reg en;

always @(posedge clk or negedge rst_n)
begin
    if (!rst_n)
    begin
        reg_a <= 0;
        reg_b <= 0;
        sum <= 0;
        en <= 0;
    end
    else if (i_en)
    begin
        reg_a <= adda;
        reg_b <= addb;
        sum <= {1'b0, reg_a} + {1'b0, reg_b};
        en <= 1;
    end
        en <= 0;
end

assign result = sum;
assign o_en = en;

endmodule

module LIFObuffer
(
    input [3:0] dataIn,
    input RW,
    input EN,
    input Rst,
    input Clk,
    output EMPTY,
    output FULL,
    output reg [3:0] dataOut
);

reg [3:0] stack_mem [0:3];
reg [2:0] SP;

always @(posedge Clk) begin
    if (Rst) begin
        SP <= 4;
        stack_mem[0] <= 0;
        stack_mem[1] <= 0;
        stack_mem[2] <= 0;
        stack_mem[3] <= 0;
    end else if (EN) begin
        if (!RW && !FULL) begin
            stack_mem[--SP] <= dataIn;
        end else if (RW && !EMPTY) begin
            dataOut <= stack_mem[SP++];
            stack_mem[SP-1] <= 0;
        end
    end
end

assign EMPTY = (SP == 4);
assign FULL = (SP == 0);

endmodule

module synchronizer
(
    input clk_a,
    input clk_b,
    input arstn,
    input brstn,
    input [3:0] data_in,
    input data_en,
    output reg [3:0] dataout
);

reg [3:0] data_reg;
reg [3:0] en_data_reg;
reg en_clap_one;
reg en_clap_two;

always @(posedge clk_a or negedge arstn) begin
    if (!arstn) begin
        data_reg <= 4'b0;
    end else begin
        data_reg <= data_in;
    end
end

always @(posedge clk_a or negedge arstn) begin
    if (!arstn) begin
        en_data_reg <= 4'b0;
    end else begin
        en_data_reg <= data_en;
    end
end

always @(posedge clk_b or negedge brstn) begin
    if (!brstn) begin
        en_clap_one <= 1'b0;
        en_clap_two <= 1'b0;
    end else begin
        en_clap_one <= en_data_reg;
        en_clap_two <= en_clap_one;
    end
end

always @(posedge clk_b or negedge brstn) begin
    if (!brstn) begin
        dataout <= 4'b0;
    end else begin
        if (en_clap_two) begin
            dataout <= data_reg;
        end else begin
            dataout <= dataout;
        end
    end
end
endmodule

