module JC_counter
(
    input clk,
    input rst_n
);

    reg [63:0] q;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n)
            q <= 64'b0;
        else if(q[0] == 1'b0) q <= {~q[0], q[63:1]}; else q <= {q[63:1], ~q[0]};
    end

endmodule

module accu
(
    input clk,
    input rst_n,
    input [7:0] data_in,
    input valid_in,
    output valid_out,
    output [9:0] data_out
);

reg [9:0] sum;
reg [3:0] count;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sum <= 0;
        count <= 0;
    end else if (valid_in) begin
        sum <= sum + data_in;
        count <= count + 1;
    end
end

assign valid_out = (count == 4'b1000) ? 1 : 0;
assign data_out = sum;

endmodule

module radix2_div
(
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output res_valid,
    output [15:0] result
);

reg [7:0] dividend_reg;
reg [7:0] divisor_reg;
reg [15:0] result_reg;
reg [3:0] cnt;
reg start_cnt;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        dividend_reg <= 8'b0;
        divisor_reg <= 8'b0;
        result_reg <= 16'b0;
        cnt <= 4'b0;
        start_cnt <= 1'b0;
    end else if (opn_valid && !res_valid) begin
        dividend_reg <= dividend;
        divisor_reg <= divisor;
        result_reg <= {8'b0, dividend};
        cnt <= 4'd1;
        start_cnt <= 1'b1;
    end else if (start_cnt) begin
        if (cnt == 4'd8) begin
            start_cnt <= 1'b0;
            result_reg <= {result_reg[7], result_reg[15:8]};
        end else begin
            cnt <= cnt + 1'b1;
            result_reg <= {result_reg[7], result_reg[15:8]};
        end
    end
end

assign res_valid = start_cnt ? 1'b0 : 1'b1;
assign result = result_reg;

endmodule

module multi_pipe_8bit
(
    input clk,
    input rst_n,
    input mul_en_in,
    input mul_a,
    input mul_b,
    output mul_en_out,
    output mul_out
);

reg [2:0] mul_en_out_reg;
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        mul_en_out_reg <= 3'b000;
    end else begin
        mul_en_out_reg <= {mul_en_out_reg[1:0], mul_en_in};
    end
end
assign mul_en_out = mul_en_out_reg[2];

reg [7:0] mul_a_reg;
reg [7:0] mul_b_reg;
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        mul_a_reg <= 8'b0;
        mul_b_reg <= 8'b0;
    end else begin
        if (mul_en_in) begin
            mul_a_reg <= mul_a;
            mul_b_reg <= mul_b;
        end
    end
end

wire [7:0] temp[7:0];
genvar i;
generate
    for (i = 0; i < 8; i = i + 1) begin : pp_gen
        assign temp[i] = mul_b_reg[i] ? (mul_a_reg << i) : 8'b0;
    end
endgenerate

reg [15:0] sum[7:0];
integer j;
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        for (j = 0; j < 8; j = j + 1) begin
            sum[j] <= 16'b0;
        end
    end else begin
        for (j = 0; j < 8; j = j + 1) begin
            sum[j] <= temp[j] + sum[j];
        end
    end
end

reg [15:0] mul_out_reg;
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        mul_out_reg <= 16'b0;
    end else begin
        mul_out_reg <= sum[0] + sum[1] + sum[2] + sum[3] +
                       sum[4] + sum[5] + sum[6] + sum[7];
    end
end

assign mul_out = mul_en_out ? mul_out_reg : 16'b0;
endmodule

module freq_divbyodd
(
    input clk,
    input rst_n,
    output clk_div
);

parameter NUM_DIV = 5;

reg [7:0] cnt1, cnt2;
reg clk_div1, clk_div2;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        cnt1 <= 8'b0;
        cnt2 <= 8'b0;
        clk_div1 <= 1'b0;
        clk_div2 <= 1'b0;
    end else begin
        if (cnt1 == NUM_DIV / 2 - 1)
            clk_div1 <= ~clk_div1;
        if (cnt2 == NUM_DIV / 2 - 1)
            clk_div2 <= ~clk_div2;
        cnt1 <= cnt1 + 1;
        cnt2 <= cnt2 + 1;
    end
end

assign clk_div = clk_div1 | clk_div2;

endmodule

module serial2parallel
(
    input clk,
    input rst_n,
    input din_serial,
    input din_valid,
    output reg dout_parallel,
    output reg dout_valid
);

reg [7:0] shift_reg;
integer cnt;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        shift_reg <= 8'b0;
        dout_parallel <= 8'b0;
        dout_valid <= 1'b0;
        cnt <= 0;
    end else begin
        if (din_valid) begin
            shift_reg <= {shift_reg[6:0], din_serial};
            cnt <= cnt + 1;

            if (cnt == 8'd7) begin
                dout_parallel <= shift_reg;
                dout_valid <= 1'b1;
                cnt <= 0;
            end else begin
                dout_valid <= 1'b0;
            end
        end
    end
end

endmodule

module sequence_detector
(
    input clk,
    input reset_n,
    input data_in,
    output sequence_detected
);

localparam IDLE = 4'b0000;
localparam S1 = 4'b0001;
localparam S2 = 4'b0010;
localparam S3 = 4'b0011;
localparam S4 = 4'b0100;

reg [1:0] state;
reg sequence_found;

always @(posedge clk or negedge reset_n)
begin
    if (!reset_n)
    begin
        state <= IDLE;
        sequence_found <= 1'b0;
    end
    begin
        case (state)
            IDLE: begin
                if (data_in == 1'b1) state <= S1; else state <= IDLE;
            end
            S1: begin
                if (data_in == 1'b0) state <= S2; else state <= IDLE;
            end
            S2: begin
                if (data_in == 1'b0) state <= S3; else state <= IDLE;
            end
            S3: begin
                if (data_in == 1'b1) state <= S4; else state <= IDLE;
            end
            S4: begin
                if (data_in == 1'b1) state <= S1; else state <= IDLE;
            end
            default: state <= IDLE;
        endcase
    end
end

assign sequence_detected = sequence_found;

endmodule
